export type Method={slug:string;title:Bi;summary:Bi;origin:Bi;principles:Bi[];flow:Bi;roles:Bi;artifacts:Bi;cadence:Bi;metrics:Bi;strengths:Bi;limitations:Bi;prerequisites:Bi;bestFit:Bi;poorFit:Bi;antiPatterns:Bi;tailoring:Bi;combinations:Bi;checklist:Bi[];sourceIds:string[];version:string;updatedAt:string};
const m=(slug:string,ru:string,en:string,summaryRu:string,summaryEn:string,flowRu:string,flowEn:string,bestRu:string,bestEn:string,limitsRu:string,limitsEn:string,sourceIds:string[],version="Practice") :Method=>({
  slug,title:{ru,en},summary:{ru:summaryRu,en:summaryEn},origin:{ru:"Возник как ответ на определённый контекст управления; используйте происхождение для понимания допущений, а не как знак универсальности.",en:"Emerged for a specific management context; use its origin to understand assumptions, not as proof of universality."},
  principles:[{ru:"Явно определить способ принятия решений и поток работы.",en:"Make decision rights and work flow explicit."},{ru:"Подбирать контроль пропорционально риску и неопределённости.",en:"Tailor control to risk and uncertainty."},{ru:"Замыкать цикл план → работа → обратная связь → адаптация.",en:"Close the plan → work → feedback → adaptation loop."}],
  flow:{ru:flowRu,en:flowEn},roles:{ru:"Роли определяются выбранным подходом; владелец результата, руководитель проекта и исполнители должны иметь ясные полномочия.",en:"Roles follow the chosen approach; outcome owner, project lead, and delivery team need clear decision rights."},
  artifacts:{ru:"Используйте только те артефакты, которые поддерживают решение, координацию, проверку или ответственность.",en:"Use only artifacts that support a decision, coordination, verification, or accountability."},
  cadence:{ru:"Каденция зависит от скорости обратной связи, стоимости координации и риска задержки.",en:"Cadence depends on feedback speed, coordination cost, and delay risk."},metrics:{ru:"Смотрите на результат, predictability, flow, качество и риск — не на объём активности.",en:"Track outcomes, predictability, flow, quality, and risk—not activity volume."},
  strengths:{ru:"Даёт общую операционную модель и язык координации, если совпадает с контекстом.",en:"Provides a shared operating model and coordination language when context fits."},limitations:{ru:limitsRu,en:limitsEn},prerequisites:{ru:"Общая цель, явные владельцы, доступ к обратной связи и дисциплина обновления рабочих данных.",en:"Shared goal, explicit ownership, access to feedback, and discipline in updating work data."},bestFit:{ru:bestRu,en:bestEn},poorFit:{ru:"Среда, где ключевые допущения подхода отсутствуют или конфликтуют с governance.",en:"Environments where core assumptions are absent or conflict with governance."},antiPatterns:{ru:"Механическое выполнение церемоний; показатели как цель; добавление слоёв без удаления лишних.",en:"Mechanical ceremonies; metrics as targets; adding layers without removing waste."},tailoring:{ru:"Начните с минимально достаточной структуры и усиливайте контроль только по наблюдаемой потребности.",en:"Start with minimum sufficient structure and add control only for an observed need."},combinations:{ru:"Комбинируйте governance, planning и execution как отдельные слои; явно фиксируйте конфликты допущений.",en:"Combine governance, planning, and execution as separate layers; expose conflicting assumptions."},
  checklist:[{ru:"Сформулировать ожидаемый результат и ограничения.",en:"State the expected outcome and constraints."},{ru:"Определить владельцев решений и cadence.",en:"Define decision owners and cadence."},{ru:"Выбрать минимум артефактов и метрик.",en:"Select the minimum artifacts and metrics."},{ru:"Провести review через один рабочий цикл.",en:"Review after one working cycle."}],sourceIds,version,updatedAt:"2026-09-04"});

export const methods:Method[]=[
  m("predictive","Предиктивное управление","Predictive project management","Детальное предварительное планирование и контроль относительно baseline.","Plan substantial scope in advance and control delivery against a baseline.","Инициация → планирование → исполнение → контроль → закрытие.","Initiate → plan → execute → control → close.","Стабильный scope, формальные approvals, высокая стоимость изменений.","Stable scope, formal approvals, high change cost.","Плохо переносит частую смену требований и позднюю обратную связь.","Handles frequent requirement change and late feedback poorly.",["pmbok8","iso21502"]),
  m("waterfall","Waterfall","Waterfall","Последовательная модель фаз с формализованными переходами.","Sequential phase model with formal transitions.","Требования → design → build → verify → transition.","Requirements → design → build → verify → transition.","Повторяемая работа с предсказуемыми interfaces и gates.","Repeatable work with predictable interfaces and gates.","Ошибки предположений обнаруживаются поздно.","Wrong assumptions may surface late.",["iso21502"]),
  m("agile","Agile","Agile","Система ценностей для адаптивной разработки через частую поставку и обучение.","A value system for adaptive delivery through frequent value and learning.","Короткие циклы: выбрать ценность → сделать → проверить → адаптировать.","Short loops: choose value → deliver → inspect → adapt.","Высокая неопределённость и доступная частая обратная связь.","High uncertainty with frequent accessible feedback.","Без ясной цели и empowered team превращается в реактивность.","Without a clear goal and empowered team it becomes reactive.",["agilemanifesto","agile2"]),
  m("hybrid","Гибридный подход","Hybrid","Осмысленное сочетание governance и adaptive delivery.","Purposeful combination of governance and adaptive delivery.","Формальные контрольные точки окружают короткие циклы delivery.","Formal control points surround short delivery cycles.","Жёсткие внешние ограничения при изменчивом способе достижения результата.","Hard external constraints with an evolving solution path.","Без явных границ становится случайным framework soup.","Without explicit boundaries it becomes random framework soup.",["pmbok8","agile2"]),
  m("scrum","Scrum","Scrum","Лёгкий framework для сложных продуктов на основе empiricism.","A lightweight framework for complex products based on empiricism.","Product Backlog → Sprint Planning → Sprint → Review + Retrospective → adaptation.","Product Backlog → Sprint Planning → Sprint → Review + Retrospective → adaptation.","Кросс-функциональная команда может создавать usable increment каждый Sprint.","A cross-functional team can create a usable Increment every Sprint.","Не решает portfolio, contracts и governance автоматически.","Does not automatically solve portfolio, contracts, or governance.",["scrum2020"],"Scrum Guide 2020"),
  m("kanban","Kanban","Kanban","Оптимизация потока через явный workflow, контроль WIP и обратную связь.","Flow optimization through an explicit workflow, WIP control, and feedback.","Определить workflow → управлять WIP → наблюдать flow metrics → улучшать.","Define workflow → control WIP → observe flow metrics → improve.","Непрерывный поток разнородной работы и потребность сократить задержки.","Continuous heterogeneous work where reducing delay matters.","Доска без WIP и flow reviews даёт только визуализацию задач.","A board without WIP control and flow reviews only visualizes tasks.",["kanban2025"],"Kanban Guide May 2025"),
  m("scrumban","Scrumban","Scrumban","Scrum cadence с Kanban flow practices и эволюционным улучшением.","Scrum cadence combined with Kanban flow practices and evolutionary improvement.","Sprint goal и reviews сохраняются; WIP, pull и flow metrics управляют исполнением.","Sprint goal and reviews remain; WIP, pull, and flow metrics govern execution.","Команда Scrum испытывает перегрузку, carry-over или interrupt work.","A Scrum team faces overload, carry-over, or interrupt work.","Название не заменяет явного Definition of Workflow.","The label does not replace an explicit Definition of Workflow.",["scrum2020","kanban2025"]),
  m("lean","Lean","Lean","Управление ценностью, потоком, качеством и устранением потерь.","Manage value, flow, quality, and waste elimination.","Определить value → map flow → remove constraints → improve continuously.","Define value → map flow → remove constraints → improve continuously.","Повторяемые value streams и измеримые задержки.","Repeatable value streams with observable delays.","Локальная экономия может повредить системному результату.","Local optimization can harm the system outcome.",["kanban2025"]),
  m("xp","Экстремальное программирование","Extreme Programming","Инженерные практики для быстрой и устойчивой поставки software.","Engineering practices for rapid, sustainable software delivery.","Малые releases, tests, continuous integration, pair work, refactoring.","Small releases, tests, continuous integration, pair work, refactoring.","Software teams с частыми изменениями и сильной инженерной дисциплиной.","Software teams with frequent change and strong engineering discipline.","Практики требуют skill и не заменяют product direction.","Practices require skill and do not replace product direction.",["agilemanifesto"]),
  m("prince2","PRINCE2","PRINCE2","Структурированный метод управления через принципы, практики, процессы и tailoring.","Structured project management through principles, practices, processes, and tailoring.","Business justification и управление по стадиям с определёнными решениями.","Continued business justification and management by stages with defined decisions.","Организации с formal governance и ясной ответственностью.","Organizations needing formal governance and clear accountability.","Плохой tailoring создаёт документную нагрузку без лучшего контроля.","Poor tailoring creates document load without better control.",["prince2v7"],"PRINCE2 7"),
  m("cpm","Метод критического пути","Critical Path Method","Сетевая модель schedule, показывающая цепочку без total float.","A schedule network model identifying the chain with no total float.","Dependencies + durations → forward pass → backward pass → float.","Dependencies + durations → forward pass → backward pass → float.","Проекты с зависимыми activity и достаточно стабильными estimates.","Projects with dependent activities and reasonably stable estimates.","Результат зависит от качества зависимостей и оценок.","Output is only as good as dependencies and estimates.",["pmbok8"]),
  m("critical-chain","Критическая цепь","Critical Chain","Планирование с учётом resource constraints и aggregate buffers.","Planning that considers resource constraints and aggregate buffers.","Resource-level schedule → critical chain → project/feeding buffers → buffer control.","Resource-level schedule → critical chain → project/feeding buffers → buffer control.","Мультипроектная среда с конкуренцией за ограниченные ресурсы.","Multi-project environments competing for constrained resources.","Некорректные buffers маскируют плохие исходные данные.","Poorly designed buffers can mask weak inputs.",["pmbok8"]),
  m("stage-gate","Stage-Gate","Stage-Gate","Инвестиционные решения между стадиями развития инициативы.","Investment decisions between stages of initiative development.","Stage work → evidence package → gate decision: go/hold/recycle/stop.","Stage work → evidence package → gate decision: go/hold/recycle/stop.","Высокая стоимость следующей стадии и необходимость portfolio choices.","High next-stage cost and portfolio choices.","Gates становятся театром, если stop decision невозможен.","Gates become theater when stopping is impossible.",["pmbok8"]),
  m("lean-startup","Lean Startup","Lean Startup","Проверка бизнес-гипотез через build–measure–learn.","Testing business hypotheses through build–measure–learn.","Гипотеза → минимальный эксперимент → evidence → pivot/persevere.","Hypothesis → minimum experiment → evidence → pivot/persevere.","Новый продукт с высокой market uncertainty.","New products with high market uncertainty.","MVP может быть принят за низкокачественный конечный продукт.","An MVP can be mistaken for a low-quality final product.",["agile2"]),
  m("design-thinking","Дизайн-мышление","Design Thinking","Human-centered exploration and solution framing.","Human-centered exploration and solution framing.","Empathize → define → ideate → prototype → test; loops are expected.","Empathize → define → ideate → prototype → test; loops are expected.","Нечёткая проблема и необходимость понять поведение пользователя.","Ambiguous problem requiring user understanding.","Идеация без delivery и evidence не создаёт результат.","Ideation without delivery and evidence creates no outcome.",["agile2"]),
  m("scaling","Масштабирование: SAFe, LeSS, DA","Scaling: SAFe, LeSS, DA","Нейтральная карта подходов координации нескольких команд.","A neutral map of approaches for coordinating multiple teams.","Синхронизация strategy, architecture, delivery и feedback различается по framework.","Strategy, architecture, delivery, and feedback synchronization varies by framework.","Реальная межкомандная связанность, которую нельзя устранить проще.","Real cross-team coupling that cannot be removed more simply.","Scaling framework усиливает существующую сложность и не лечит слабые teams.","A scaling framework amplifies complexity and does not repair weak teams.",["agile2"]),
];

export type Template={slug:string;title:Bi;category:string;purpose:Bi;when:Bi;fields:Bi[];guidance:Bi;antiPattern:Bi};
const tf={
  strategy:[{ru:"Контекст и решение",en:"Context and decision"},{ru:"Ожидаемый результат",en:"Expected outcome"},{ru:"Критерий успеха",en:"Success measure"},{ru:"Владелец",en:"Owner"}],
  plan:[{ru:"Scope / границы",en:"Scope / boundaries"},{ru:"Milestones и даты",en:"Milestones and dates"},{ru:"Зависимости",en:"Dependencies"},{ru:"Риски и допущения",en:"Risks and assumptions"}],
  log:[{ru:"ID и дата",en:"ID and date"},{ru:"Описание",en:"Description"},{ru:"Владелец",en:"Owner"},{ru:"Статус и следующее действие",en:"Status and next action"}],
  meeting:[{ru:"Цель встречи",en:"Meeting purpose"},{ru:"Подготовка",en:"Preparation"},{ru:"Agenda и timeboxes",en:"Agenda and timeboxes"},{ru:"Решения и actions",en:"Decisions and actions"}],
  control:[{ru:"Baseline / ожидание",en:"Baseline / expectation"},{ru:"Факт",en:"Actual"},{ru:"Отклонение",en:"Variance"},{ru:"Решение и владелец",en:"Decision and owner"}],
};
const template=(slug:string,ru:string,en:string,category:keyof typeof tf,purposeRu:string,purposeEn:string,extra:Bi[]=[]):Template=>({slug,title:{ru,en},category,purpose:{ru:purposeRu,en:purposeEn},when:{ru:"Используйте, когда артефакт помогает принять решение, синхронизировать участников или подтвердить результат.",en:"Use when the artifact supports a decision, aligns participants, or verifies an outcome."},fields:[...tf[category],...extra],guidance:{ru:"Заполняйте до уровня, достаточного для следующего управленческого действия. Удалите секции, которые ничего не меняют.",en:"Complete only to the depth needed for the next management action. Remove sections that change nothing."},antiPattern:{ru:"Документ обновляется ради отчётности, но не используется в решениях.",en:"The document is maintained for reporting but never used in decisions."}});

