export type Playbook={slug:string;title:Bi;diagnose:Bi[];immediate:Bi[];next:Bi[];stabilize:Bi[];prevent:Bi[];metrics:Bi[];antiPatterns:Bi[]};
const pb=(slug:string,ru:string,en:string,signalRu:string,signalEn:string,actionRu:string,actionEn:string,metricRu:string,metricEn:string):Playbook=>({slug,title:{ru,en},diagnose:[{ru:signalRu,en:signalEn},{ru:"Отделите наблюдаемый факт от интерпретации и найдите ограничение системы.",en:"Separate observed fact from interpretation and identify the system constraint."}],immediate:[{ru:actionRu,en:actionEn},{ru:"Назначьте одного владельца следующего решения и срок проверки.",en:"Assign one owner for the next decision and a review date."}],next:[{ru:"В следующий рабочий цикл соберите минимальные данные, перепланируйте затронутую работу и сообщите последствия.",en:"In the next working cycle, collect minimum evidence, replan affected work, and communicate impact."}],stabilize:[{ru:"Сократите активную работу, сделайте приоритеты и зависимости явными, восстановите cadence контроля.",en:"Reduce active work, expose priorities and dependencies, and restore a control cadence."}],prevent:[{ru:"Добавьте ранний trigger, владельца и регулярный review — не новый отчёт ради отчёта.",en:"Add an early trigger, owner, and regular review—not another report for its own sake."}],metrics:[{ru:metricRu,en:metricEn},{ru:"Возраст блокировок и время до решения.",en:"Blocker age and time to decision."}],antiPatterns:[{ru:"Обещать новую дату до анализа причин и trade-offs.",en:"Promise a new date before analyzing causes and trade-offs."},{ru:"Увеличивать параллельную работу, чтобы создать видимость скорости.",en:"Increase parallel work to create an appearance of speed."}]});

